 api.GET("/conversations",func(c *gin.Context){var ms []ConversationMember;if e:=db.Where("user_id=?",uid(c)).Find(&ms).Error;e!=nil{c.JSON(500,gin.H{"error":"list failed"});return};ids:=make([]string,0,len(ms));for _,m:=range ms{ids=append(ids,m.ConversationID)};var cs []Conversation;if len(ids)>0{if e:=db.Where("id IN ?",ids).Order("updated_at DESC").Find(&cs).Error;e!=nil{c.JSON(500,gin.H{"error":"list failed"});return}};type conversationView struct{Conversation;MemberIDs []string `json:"memberIds"`;UnreadCount int64 `json:"unreadCount"`};out:=make([]conversationView,0,len(cs));if len(cs)>0{memberRows:=make([]ConversationMember,0);if e:=db.Where("conversation_id IN ?",ids).Find(&memberRows).Error;e!=nil{c.JSON(500,gin.H{"error":"list members failed"});return};memberMap:=map[string][]string{};for _,m:=range memberRows{memberMap[m.ConversationID]=append(memberMap[m.ConversationID],m.UserID)};unreadRows:=make([]struct{ConversationID string `gorm:"column:conversation_id"`;Count int64 `gorm:"column:count"`},0);if e:=db.Raw("SELECT m.conversation_id, COUNT(*) AS count FROM messages m WHERE m.conversation_id IN ? AND m.sender_id <> ? AND NOT EXISTS (SELECT 1 FROM read_receipts r WHERE r.message_id=m.id AND r.user_id=?) GROUP BY m.conversation_id",ids,uid(c),uid(c)).Scan(&unreadRows).Error;e!=nil{c.JSON(500,gin.H{"error":"unread count failed"});return};unreadMap:=map[string]int64{};for _,row:=range unreadRows{unreadMap[row.ConversationID]=row.Count};for _,conv:=range cs{out=append(out,conversationView{Conversation:conv,MemberIDs:memberMap[conv.ID],UnreadCount:unreadMap[conv.ID]})}};c.JSON(200,out)})
 api.GET("/conversations/:id/messages",func(c *gin.Context){id:=c.Param("id");if !requireMember(db,c,id){return};limit,_:=strconv.Atoi(c.DefaultQuery("limit","50"));if limit<1||limit>100{limit=50};before:=strings.TrimSpace(c.Query("before"));var ms []Message;q:=db.Where("conversation_id=?",id);if before!=""{var cursor Message;if db.Where("id=? AND conversation_id=?",before,id).First(&cursor).Error!=nil{c.JSON(400,gin.H{"error":"invalid cursor"});return};q=q.Where("(created_at < ?) OR (created_at = ? AND id < ?)",cursor.CreatedAt,cursor.CreatedAt,cursor.ID)};if e:=q.Order("created_at DESC,id DESC").Limit(limit+1).Find(&ms).Error;e!=nil{c.JSON(500,gin.H{"error":"history failed"});return};hasMore:=len(ms)>limit;if hasMore{ms=ms[:limit]};for i,j:=0,len(ms)-1;i<j;i,j=i+1,j-1{ms[i],ms[j]=ms[j],ms[i]};nextBefore:="";if hasMore&&len(ms)>0{nextBefore=ms[0].ID};c.JSON(200,gin.H{"messages":ms,"nextBefore":nextBefore,"hasMore":hasMore})})
