 api.POST("/conversations/:id/read-through",func(c *gin.Context){id:=c.Param("id");if !requireMember(db,c,id){return};var in struct{MessageID string `json:"messageId"`};if c.BindJSON(&in)!=nil||in.MessageID==""{c.JSON(400,gin.H{"error":"messageId required"});return};var target Message;if db.Where("id=? AND conversation_id=?",in.MessageID,id).First(&target).Error!=nil{c.JSON(404,gin.H{"error":"message not found"});return};if target.SenderID==uid(c){c.JSON(400,gin.H{"error":"cannot mark own message as read"});return};now:=time.Now();if e:=db.Exec(`INSERT INTO read_receipts (message_id,user_id,read_at) SELECT m.id,?,? FROM messages m WHERE m.conversation_id=? AND m.sender_id<>? AND (m.created_at < ? OR (m.created_at = ? AND m.id <= ?)) ON CONFLICT (message_id,user_id) DO UPDATE SET read_at=EXCLUDED.read_at`,uid(c),now,id,uid(c),target.CreatedAt,target.CreatedAt,target.ID).Error;e!=nil{c.JSON(500,gin.H{"error":"mark read failed"});return};h.broadcast(id,gin.H{"type":"read_through","messageId":target.ID,"userId":uid(c),"readAt":now});c.JSON(200,gin.H{"ok":true});return});api.POST("/conversations/:id/read",func(c *gin.Context){id:=c.Param("id");if !requireMember(db,c,id){return};var in struct{MessageID string `json:"messageId"`};if c.BindJSON(&in)!=nil||in.MessageID==""{c.JSON(400,gin.H{"error":"messageId required"});return};var m Message;if db.Where("id=? AND conversation_id=?",in.MessageID,id).First(&m).Error!=nil{c.JSON(404,gin.H{"error":"message not found"});return};if m.SenderID==uid(c){c.JSON(400,gin.H{"error":"cannot mark own message as read"});return};now:=time.Now();if e:=db.Where("message_id=? AND user_id=?",in.MessageID,uid(c)).Assign(ReadReceipt{MessageID:in.MessageID,UserID:uid(c),ReadAt:now}).FirstOrCreate(&ReadReceipt{}).Error;e!=nil{c.JSON(500,gin.H{"error":"mark read failed"});return};h.broadcast(id,gin.H{"type":"read","messageId":in.MessageID,"userId":uid(c),"readAt":now});c.JSON(200,gin.H{"ok":true})})
